;=====================================================================
;  "THE SONG OF THE GERMANS" - 3RD VERSE
;  C64 program, ACME syntax
;
;  Picture : multicolor bitmap 320x200, portrait of the federal
;            president + text of the third verse
;  Music   : SID arrangement of the Haydn melody, 3 voices, 50 Hz IRQ
;
;  Build   :  ninja            (see build.ninja)
;  Files   :  screen.bin, colors.bin, bitmap.bin, freq.bin, music.bin
;             (generated by make_data.py)
;  Start   :  LOAD"ANTHEM",8,1   or   RUN
;=====================================================================

!to "anthem.prg", cbm

;--- BASIC line  10 SYS 2061 ----------------------------------------
* = $0801
        !word $080b
        !word 10
        !byte $9e
        !text "2061"
        !byte 0
        !word 0

;--- Zero page ------------------------------------------------------
mptr    = $fb           ; pointer into the music data
durcnt  = $fd           ; remaining note duration in 1/50 s
pwmcnt  = $fe           ; pulse width modulation counter
prev1   = $f7           ; last note played, voice 1..3
prev2   = $f8
prev3   = $f9

;=====================================================================
* = $080d
start
        sei
        lda #$7f
        sta $dc0d       ; CIA timer IRQs off
        lda $dc0d

        lda #$03
        sta $dd00       ; VIC bank 0 ($0000-$3fff)
        lda #$18
        sta $d018       ; bitmap $2000, screen $0400
        lda #$3b
        sta $d011       ; bitmap mode, 25 rows
        lda #$d8
        sta $d016       ; multicolor, 40 columns
        lda #$00
        sta $d020       ; border black
        sta $d021       ; background black

;--- Copy picture data ----------------------------------------------
        ldx #$00
copy    lda screen,x
        sta $0400,x
        lda screen+$100,x
        sta $0500,x
        lda screen+$200,x
        sta $0600,x
        lda screen+$300,x
        sta $0700,x
        lda colors,x
        sta $d800,x
        lda colors+$100,x
        sta $d900,x
        lda colors+$200,x
        sta $da00,x
        lda colors+$300,x
        sta $db00,x
        inx
        bne copy

;--- SID ------------------------------------------------------------
        ldx #$18
        lda #$00
sidclr  sta $d400,x
        dex
        bpl sidclr
        lda #$0f
        sta $d418       ; volume 15, filter off

        lda #$00        ; voice 1: melody, pulse wave
        sta $d402
        lda #$0c
        sta $d403       ; pulse width $0c00
        lda #$09
        sta $d405       ; attack 0, decay 9
        lda #$a8
        sta $d406       ; sustain 10, release 8

        lda #$00        ; voice 2: bass, triangle
        sta $d409
        lda #$0c
        sta $d40a
        lda #$00
        sta $d40c
        lda #$a9
        sta $d40d

        lda #$00        ; voice 3: pad, sawtooth
        sta $d410
        lda #$08
        sta $d411
        lda #$09
        sta $d413
        lda #$66
        sta $d414

;--- Raster IRQ -----------------------------------------------------
        lda #$fb
        sta $d012       ; raster line 251
        lda $d011
        and #$7f
        sta $d011
        lda #$01
        sta $d01a
        lda #<irq
        sta $0314
        lda #>irq
        sta $0315
        lda #1
        sta durcnt
        lda #0          ; no note played yet -> first note sounds
        sta prev1
        sta prev2
        sta prev3
        lda #<music
        sta mptr
        lda #>music
        sta mptr+1
        cli

main    jmp main        ; everything else is done by the IRQ

;--- IRQ ------------------------------------------------------------
irq     pha
        txa
        pha
        tya
        pha
        lda #$01
        sta $d019       ; acknowledge IRQ
        jsr tick
        pla
        tay
        pla
        tax
        pla
        jmp $ea31       ; KERNAL IRQ exit

;--- Tick: one step every 20 ms, pulse width drifts slowly ----------
tick    dec durcnt
        bne tick1
        jsr nextev
tick1   inc pwmcnt
        lda pwmcnt
        and #$03
        bne tick2
        inc $d403
        lda $d403
        cmp #$10
        bcc tick2
        lda #$08
        sta $d403
tick2   rts

;--- Fetch next block: note1, note2, note3, duration ----------------
nextev  ldy #0
        lda (mptr),y
        cmp #$ff
        bne nextev1
        lda #<music     ; end -> start over
        sta mptr
        lda #>music
        sta mptr+1
nextev1 ldy #0
        lda (mptr),y
        jsr set1
        ldy #1
        lda (mptr),y
        jsr set2
        ldy #2
        lda (mptr),y
        jsr set3
        ldy #3
        lda (mptr),y
        sta durcnt
        lda mptr
        clc
        adc #4
        sta mptr
        bcc nextev2
        inc mptr+1
nextev2 rts

;--- Voice 1 (A = MIDI note, 0 = rest) ------------------------------
set1    cmp #$00
        bne set1a
        lda #$40
        sta $d404
        lda #$00
        sta prev1
        rts
set1a   cmp prev1
        beq set1b       ; same note -> gate stays open
        sta prev1
        sec
        sbc #36
        asl
        tay
        lda freqtbl,y
        sta $d400
        lda freqtbl+1,y
        sta $d401
        lda #$41        ; pulse wave + gate
        sta $d404
set1b   rts

;--- Voice 2 (bass) -------------------------------------------------
set2    cmp #$00
        bne set2a
        lda #$40
        sta $d40b
        lda #$00
        sta prev2
        rts
set2a   cmp prev2
        beq set2b
        sta prev2
        sec
        sbc #36
        asl
        tay
        lda freqtbl,y
        sta $d407
        lda freqtbl+1,y
        sta $d408
        lda #$11        ; triangle + gate
        sta $d40b
set2b   rts

;--- Voice 3 (pad) --------------------------------------------------
set3    cmp #$00
        bne set3a
        lda #$40
        sta $d412
        lda #$00
        sta prev3
        rts
set3a   cmp prev3
        beq set3b
        sta prev3
        sec
        sbc #36
        asl
        tay
        lda freqtbl,y
        sta $d40e
        lda freqtbl+1,y
        sta $d40f
        lda #$21        ; sawtooth + gate
        sta $d412
set3b   rts

;--- Frequency table MIDI 36..84, PAL: f * 16777216 / 985248 --------
freqtbl
        !bin "freq.bin"

;--- Music: note1, note2, note3, duration (1/50 s), $ff = end ------
music
        !bin "music.bin"

;--- Picture data ---------------------------------------------------
* = $1000
screen
        !bin "screen.bin"

* = $1400
colors
        !bin "colors.bin"

* = $2000
bitmap
        !bin "bitmap.bin"
